import{_ as i,C as r,o as n,c as h,j as d,a as e,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const q=JSON.parse('{"title":"文字提示","description":"","frontmatter":{},"headers":[],"relativePath":"components/tooltip.md","filePath":"components/tooltip.md","lastUpdated":1787173379000}'),s={name:"components/tooltip.md"},p={id:"文字提示",tabindex:"-1"};function b(u,t,x,m,g,f){const l=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",p,[t[0]||(t[0]=e("文字提示 ",-1)),o(l,{type:"info",text:"tooltip"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#文字提示","aria-label":'Permalink to "文字提示 <Badge type="info" text="tooltip" />"'},"​",-1))]),t[3]||(t[3]=c('<p>悬停或聚焦时出现的一句纯文字说明。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>补充说明一个图标按钮是什么、一个截断的文字全文是什么。</li><li>内容是纯文字，且没有任何可交互元素。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>内容里有按钮或链接：用<a href="./popover">气泡卡片</a>——提示是够不着的。</li><li>信息重要到不能错过：写在界面上，别藏进悬停。</li><li>触摸设备是主要场景：那里没有悬停。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>openDelay</code> / <code>closeDelay</code> 防止指针路过时一路闪。</li><li>聚焦也能触发，键盘用户拿得到。</li><li>语气与尺寸两轴。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>悬停或聚焦触发器即出；指针停在提示上也不收起</p>',10)),o(a,{src:"tooltip/01-basic"}),t[4]||(t[4]=d("h3",{id:"朝向",tabindex:"-1"},[e("朝向 "),d("a",{class:"header-anchor",href:"#朝向","aria-label":'Permalink to "朝向"'},"​")],-1)),t[5]||(t[5]=d("p",null,"placement 是请求值，空间不够时由定位引擎避让；箭头跟着最终落定的那一面走",-1)),o(a,{src:"tooltip/02-placement"}),t[6]||(t[6]=d("h3",{id:"延时",tabindex:"-1"},[e("延时 "),d("a",{class:"header-anchor",href:"#延时","aria-label":'Permalink to "延时"'},"​")],-1)),t[7]||(t[7]=d("p",null,"openDelay 默认 700ms 用来防误触，closeDelay 默认 300ms 留出指针走位的余地；聚焦不走这两段等待",-1)),o(a,{src:"tooltip/03-delay"}),t[8]||(t[8]=d("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[9]||(t[9]=d("p",null,"disabled 只关掉提示本身，被包裹的触发器照样可点、可聚焦",-1)),o(a,{src:"tooltip/04-disabled"}),t[10]||(t[10]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=d("p",null,"六种语气换的是浮层实心底与其上的文字色，箭头一并跟着走；把指针停在触发器上（或用 Tab 聚焦）看差别",-1)),o(a,{src:"tooltip/05-tone"}),t[12]||(t[12]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=d("p",null,"三档换的是浮层的内边距与字号，不写 size 即缺省档；把指针停在触发器上（或用 Tab 聚焦）看差别",-1)),o(a,{src:"tooltip/06-size"}),t[14]||(t[14]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[15]||(t[15]=d("p",null,"传了 open 就由宿主说了算；悬停、聚焦、Escape 都只发意图，最终写不写由外面这份状态决定",-1)),o(a,{src:"tooltip/07-controlled"}),t[16]||(t[16]=d("h3",{id:"长文案",tabindex:"-1"},[e("长文案 "),d("a",{class:"header-anchor",href:"#长文案","aria-label":'Permalink to "长文案"'},"​")],-1)),t[17]||(t[17]=d("p",null,"提示到了宽度上限就换行，不会拉成一条横线；上限是 content 上的 --xh-tooltip-max-w 槽位",-1)),o(a,{src:"tooltip/08-long-text"}),t[18]||(t[18]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tooltip&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTooltipArrow</code> <code>XhTooltipContent</code> <code>XhTooltipPositioner</code> <code>XhTooltipRoot</code> <code>XhTooltipTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useTooltip</code></td></tr><tr><td>状态机</td><td><code>tooltipMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tooltip.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tooltip&quot;</code>：<strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <code>arrow</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td>请求的浮层朝向，默认 bottom；空间不足时由定位引擎避让。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 ltr。只改写浮层在行内轴上 start 与 end 的落点。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td>浮层与锚点的间距（px）。</td></tr><tr><td><code>openDelay</code></td><td><code>number</code></td><td></td><td>悬停进入到展开的等待毫秒，默认 700。</td></tr><tr><td><code>closeDelay</code></td><td><code>number</code></td><td></td><td>悬停移出到收起的等待毫秒，默认 300。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>只关闭提示本身，不影响被包裹控件的可用性。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定提示的底色与其上的文字色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定内边距与字号档位。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: TooltipOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>TooltipOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTooltipRoot</code></td><td><code>default</code></td><td><code>TooltipRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>closed</code> · <code>opening</code> · <code>visible</code> · <code>visible.open</code> · <code>visible.closing</code></p><p><strong>事件</strong>：<code>POINTER.ENTER</code> · <code>POINTER.LEAVE</code> · <code>POINTER.DOWN</code> · <code>FOCUS</code> · <code>BLUR</code> · <code>ESCAPE</code> · <code>OPEN</code> · <code>CLOSE</code> · <code>after.openDelay</code> · <code>after.closeDelay</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>isDisabled</code> · <code>isFocusOpened</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTooltip</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getArrowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/tooltip/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>not disabled</td><td>焦点进入 trigger 立即展开、离开立即收起，都不走延时</td></tr><tr><td><code>Escape</code></td><td>展开中且本层在层栈栈顶，或 focus in trigger 且等待展开中</td><td>立即收起，不等 closeDelay；下层浮层不受这一次按键影响</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-describedby</code></td><td><code>content</code> 部件的 id | undefined</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>arrow</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tooltip.css</code> 按部件选择：<code>[data-scope=&quot;tooltip&quot;][data-part=&quot;trigger&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>arrow</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tooltip-arrow-size</code> · <code>--xh-tooltip-bg</code> · <code>--xh-tooltip-fg</code> · <code>--xh-tooltip-font-size</code> · <code>--xh-tooltip-max-w</code> · <code>--xh-tooltip-px</code> · <code>--xh-tooltip-py</code> · <code>--xh-tooltip-radius</code> · <code>--xh-tooltip-shadow</code> · <code>--xh-tooltip-trigger-gap</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>挂在<a href="./icon">图标</a>按钮、<a href="./toggle">切换按钮</a>、<a href="./ellipsis">文本省略</a>上。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>一句话讲完，超过一行就该换别的形式。</li><li>图标按钮的可及名字要写在按钮上（<code>aria-label</code>），提示只是视觉补充。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把唯一的操作说明放进提示：触摸用户永远看不到。</li><li>提示里放链接。</li></ul>',48))])}const T=i(s,[["render",b]]);export{q as __pageData,T as default};
